  "نظام إدارة الموارد البشرية المتكامل":
    "Integrated human resources management system",
  "مقرات الشركة والفروع": "Company offices and branches",
  "لا توجد فروع مسجلة": "No branches registered",
  "سياسة الخصوصية": "Privacy policy",
  "سياسة حماية بيانات الموظفين": "Employee data protection policy",
  "آخر تحديث": "Last updated",
  "جمع البيانات": "Data collection",
  "استخدام البيانات": "Data use",
  "أمن البيانات": "Data security",
  "حقوق الموظف": "Employee rights",
  التعديلات: "Changes",
  "يجمع النظام بيانات الموظفين الضرورية لتشغيل نظام الموارد البشرية، وتشمل: البيانات الشخصية (الاسم، تاريخ الميلاد، الجنسية)، بيانات العمل (القسم، المسمى الوظيفي، الراتب)، سجلات الحضور والانصراف، وسجلات الطلبات.":
    "The system collects employee data necessary to operate the human resources system, including personal data, employment data, attendance records, and request records.",
  "تُستخدم البيانات حصرًا لأغراض إدارية داخلية كإدارة الرواتب والإجازات والحضور وإعداد التقارير الإدارية. لا تُشارك البيانات مع أي جهة خارجية دون إذن صريح.":
    "Data is used exclusively for internal administration, such as payroll, leave, attendance, and reporting. It is not shared with external parties without explicit permission.",
  "تخضع جميع البيانات لتشفير كامل أثناء النقل والتخزين. يُطبّق النظام نموذج صلاحيات دقيق يضمن وصول كل موظف فقط إلى البيانات المخصصة لدوره.":
    "All data is encrypted in transit and at rest. The system applies precise permissions so each employee accesses only data assigned to their role.",
  "لكل موظف حق الاطلاع على بياناته الشخصية وطلب تصحيح أي معلومات غير دقيقة. يمكن التواصل مع إدارة الموارد البشرية لأي استفسار يتعلق بالبيانات الشخصية.":
    "Each employee may view their personal data and request correction of inaccurate information. Contact HR with any personal-data inquiry.",
  "يحق لإدارة الشركة تحديث سياسة الخصوصية في أي وقت. سيتم إشعار الموظفين بأي تغييرات جوهرية عبر النظام.":
    "Company management may update this privacy policy at any time. Employees will be notified of material changes through the system.",
  "تفاصيل الطلب": "Request details",
