  "احتساب يوم انتهاء الخدمة ضمن مدة الخدمة": "Include the termination day within the service duration",
  "عند اختيار \u201cنعم\u201d يُحسب تاريخ انتهاء الخدمة (نفسه) ضمن احتساب مكافأة نهاية الخدمة في احتساب مدة الخدمة. هذا هو الوضع الافتراضي وفق مطابق لهذا السلوك السابق. وعند اختيار \u201cلا\u201d يُحسب مدة الخدمة بالفرق بين تاريخ المباشرة وتاريخ انتهاء الخدمة دون إضافة يوم. هذا ما يطابق حاسبة الموارد البشرية وتقارير وزارة الموارد البشرية لاحتساب جميع مستحقات نهاية الخدمة.": "When choosing \u201cYes\u201d, the termination date itself is included when calculating the end-of-service gratuity and the service duration. This is the default behavior matching the previous behavior. When choosing \u201cNo\u201d, the service duration is calculated as the difference between the start date and the termination date without adding a day. This matches the HR calculator and Ministry of Human Resources reports for calculating all end-of-service dues.",
